import { useRef, useState } from 'react';
import { Text, TextInput, Switch, Pressable, StyleSheet, KeyboardAvoidingView, Platform, Keyboard } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

export interface OnboardingFormScreenProps {
  onComplete: (preferences: { name: string; notifications: boolean }) => void;
}

export function OnboardingFormScreen({ onComplete }: OnboardingFormScreenProps): JSX.Element {
  const [name, setName] = useState('');
  const [notifications, setNotifications] = useState(false);
  const [error, setError] = useState('');
  const nameInput = useRef<TextInput>(null);

  function finish(): void {
    const trimmed = name.trim();
    if (!trimmed) {
      setError('Enter your name before continuing.');
      nameInput.current?.focus();
      return;
    }
    setError('');
    Keyboard.dismiss();
    onComplete({ name: trimmed, notifications });
  }

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView style={styles.container} behavior={Platform.OS === 'ios' ? 'padding' : 'height'}>
        <Text accessibilityRole="header" style={styles.heading}>Let's get started</Text>
        {/* TextInput retains its native editable-text semantics; RN 0.74 has no textbox role. */}
        <TextInput ref={nameInput} value={name} onChangeText={setName}
          style={styles.input} accessibilityLabel="Your name"
          accessibilityHint="Enter the name you want us to use"
          accessibilityState={{ disabled: false }} returnKeyType="done" onSubmitEditing={finish} />
        {error ? <Text accessibilityRole="alert" accessibilityLiveRegion="polite">{error}</Text> : null}
        <Text>Allow notifications</Text>
        <Switch value={notifications} onValueChange={setNotifications}
          accessibilityRole="switch" accessibilityLabel="Allow notifications"
          accessibilityHint="Choose whether to receive notifications"
          accessibilityState={{ checked: notifications, disabled: false }} />
        <Pressable onPress={finish} style={styles.button} accessibilityRole="button"
          accessibilityLabel="Finish onboarding" accessibilityHint="Saves these preferences and completes setup"
          accessibilityState={{ disabled: false }}>
          <Text>Finish</Text>
        </Pressable>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
  container: { flex: 1, justifyContent: 'center', padding: 24, gap: 16 },
  heading: { fontSize: 24, fontWeight: '700' },
  input: { borderWidth: 1, borderRadius: 8, padding: 12, minHeight: 48 },
  button: { padding: 14, minHeight: 48, alignItems: 'center', borderWidth: 1, borderRadius: 8 },
});
